import re

with open('text.gcode') as f:
    lines = f.readlines()

objs = []
cur = None
cur_id = None
for i,line in enumerate(lines):
    s = line.strip()
    if s.startswith('M486 S'):
        val = int(s.split()[1][1:])
        if val >= 0:
            cur_id = val
            if cur_id == 0:
                cur = {'start': i, 'segs': [], 'last': None}
        else:
            if cur_id == 0 and cur is not None:
                cur['end'] = i
                objs.append(cur)
                cur = None
            cur_id = None
        continue
    if cur_id != 0 or cur is None:
        continue
    if not (s.startswith('G1') or s.startswith('G0')):
        continue
    m = re.search(r'X([-0-9.]+)', s)
    x = float(m.group(1)) if m else None
    m = re.search(r'Y([-0-9.]+)', s)
    y = float(m.group(1)) if m else None
    m = re.search(r'E([-0-9.]+)', s)
    e = m is not None
    if x is None or y is None:
        cur['last'] = None
        continue
    pt = (x,y)
    if e:
        if cur['last'] is not None:
            cur['segs'].append((cur['last'], pt))
        cur['last'] = pt
    else:
        cur['last'] = None

print('num object0 segments', len(objs))

def render(segs, W=40):
    xs = [p[0] for s in segs for p in s]
    ys = [p[1] for s in segs for p in s]
    if not xs:
        return []
    xmin,xmax = min(xs), max(xs)
    ymin,ymax = min(ys), max(ys)
    H = max(10, int(W*(ymax-ymin)/(xmax-xmin))) if xmax!=xmin else 10
    if H>60: H=60
    def tx(x): return int((x-xmin)/(xmax-xmin)*(W-1)) if xmax!=xmin else 0
    def ty(y): return int((y-ymin)/(ymax-ymin)*(H-1)) if ymax!=ymin else 0
    grid = [[' ']*(W+2) for _ in range(H)]
    def line(x0,y0,x1,y1):
        dx = abs(x1-x0); dy = abs(y1-y0)
        sx = 1 if x0<x1 else -1
        sy = 1 if y0<y1 else -1
        err = dx-dy
        while True:
            if 0<=y0<H and 0<=x0<W:
                grid[y0][x0] = '#'
            if x0==x1 and y0==y1:
                break
            e2 = 2*err
            if e2 > -dy:
                err -= dy; x0 += sx
            if e2 < dx:
                err += dx; y0 += sy
    for (x0,y0),(x1,y1) in segs:
        line(tx(x0), ty(y0), tx(x1), ty(y1))
    return grid, (xmin, xmax, ymin, ymax)

for idx,o in enumerate(objs):
    res = render(o['segs'], W=50)
    if not res:
        continue
    grid,bbox = res
    print(f'--- segment {idx} lines {o["start"]}-{o["end"]} bbox {bbox[0]:.1f},{bbox[1]:.1f} {bbox[2]:.1f},{bbox[3]:.1f} ---')
    for row in grid:
        print(''.join(row))
    print()
